 * concrete prerender that resolves it.
 */
export function trackFallbackParamsAccessed(
  workUnitStore: WorkUnitStore,
  expression: string
): void {
  trackRuntimeDataAccessed(
    workUnitStore,
    PrerenderDataKind.FallbackParams,
    expression
  )
